        $this->scanner = new FakeContentScanner($spec->scannerKey, $spec->scannerVersion);
        App::instance(ContentScanner::class, $this->scanner);
        (new class
        {
            use InteractsWithVaulter;
        })->vaulterFakeStorage();
        Bus::fake();
        App::forgetInstance(ScanWorkReconciler::class);
